 async function exported(gid){await page.evaluate(()=>{document.querySelector('#stack-export')?.remove();const f=document.createElement('iframe');f.id='stack-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#stack-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#stack-export').contentDocument.querySelector('.nw-stack-card'),{},gid);}
